42	static int bk7258_devkit_pa_delay(unsigned int delay_ms)
43	{
44	  int ret;
45	
46	  /* Restart the complete short delay after a signal interruption.  This may
47	   * wait longer than requested, but never shortens the PA settling time.
48	   */
49	
50	  do
51	    {
52	      ret = nxsig_usleep(delay_ms * 1000);
53	    }
54	  while (ret == -EINTR);
55	
56	  if (ret < 0)
57	    {
58	      syslog(LOG_ERR, "BK7258 PA: delay failed: %d\n", ret);
59	    }
60	
61	  return ret;
62	}
63	
64	static void bk7258_devkit_pa_write(bool enable)
65	{
66	#if BOARD_AUDIO_PA_ACTIVE_HIGH
67	  bk7258_gpio_write(BOARD_AUDIO_PA_PIN, enable);
68	#else
69	  bk7258_gpio_write(BOARD_AUDIO_PA_PIN, !enable);
70	#endif
71	}
72	
73	static int bk7258_devkit_pa_init(FAR void *arg)
74	{
75	  int ret;
76	
77	  (void)arg;
78	
79	  /* Configure PA pin as output, initially low (PA disabled) */
80	
81	  ret = bk7258_gpio_config_output(BOARD_AUDIO_PA_PIN,
82	                                  !BOARD_AUDIO_PA_ACTIVE_HIGH);
83	  if (ret < 0)
84	    {
85	      syslog(LOG_ERR, "BK7258 PA: failed to configure GPIO%d: %d\n",
86	             BOARD_AUDIO_PA_PIN, ret);
87	      return ret;
88	    }
89	
90	  syslog(LOG_INFO, "BK7258 PA: initialized GPIO%d (active-%s)\n",
91	         BOARD_AUDIO_PA_PIN,
92	         BOARD_AUDIO_PA_ACTIVE_HIGH ? "high" : "low");
93	
94	  return OK;
95	}
96	
97	static int bk7258_devkit_pa_enable(FAR void *arg)
98	{
99	  int ret;
100	
101	  (void)arg;
102	
103	  /* Keep the PA inactive unless both settling delays succeed. */
104	
105	  ret = bk7258_devkit_pa_delay(BOARD_AUDIO_PA_PRE_ENABLE_MS);
106	  if (ret < 0)
107	    {
108	      bk7258_devkit_pa_write(false);
109	      return ret;
110	    }
111	
112	  bk7258_devkit_pa_write(true);
113	
114	  ret = bk7258_devkit_pa_delay(BOARD_AUDIO_PA_POST_ENABLE_MS);
115	  if (ret < 0)
116	    {
117	      bk7258_devkit_pa_write(false);
118	      return ret;
119	    }
120	
121	  syslog(LOG_DEBUG, "BK7258 PA: enabled\n");
122	  return OK;
123	}
124	
125	static int bk7258_devkit_pa_disable(FAR void *arg)
126	{
127	  int post_ret;
128	  int pre_ret;
129	
130	  (void)arg;
131	
132	  /* Delay failures are diagnostic only.  Once this callback returns, the
133	   * safety-critical guarantee is that the PA GPIO has been driven inactive.
134	   */
135	
136	  pre_ret = bk7258_devkit_pa_delay(BOARD_AUDIO_PA_PRE_DISABLE_MS);
137	  bk7258_devkit_pa_write(false);
138	  post_ret = bk7258_devkit_pa_delay(BOARD_AUDIO_PA_POST_DISABLE_MS);
139	
140	  if (pre_ret < 0 || post_ret < 0)
141	    {
142	      syslog(LOG_ERR,
143	             "BK7258 PA: disable delay failed (pre=%d post=%d)\n",
144	             pre_ret, post_ret);
145	    }
146	
147	  syslog(LOG_DEBUG, "BK7258 PA: disabled\n");
148	  return OK;
149	}
