119	/* BK7258 AON GPIO configuration bits. GPIO output enable is active-low. */
120	
121	#define BK7258_GPIO_OUTPUT_VALUE  (UINT32_C(1) << 1)
122	#define BK7258_GPIO_INPUT_ENABLE  (UINT32_C(1) << 2)
123	#define BK7258_GPIO_OUTPUT_DISABLE (UINT32_C(1) << 3)
124	#define BK7258_GPIO_PULL_MODE     (UINT32_C(1) << 4)
125	#define BK7258_GPIO_PULL_ENABLE   (UINT32_C(1) << 5)
126	#define BK7258_GPIO_SECOND_FUNC   (UINT32_C(1) << 6)
127	
128	static inline uint32_t bk7258_ap_gpio_read(unsigned int pin)
129	{
130	  return *(volatile uint32_t *)BK7258_GPIO_CFG(pin);
131	}
132	
133	static inline void bk7258_ap_gpio_write(unsigned int pin, uint32_t value)
134	{
135	  *(volatile uint32_t *)BK7258_GPIO_CFG(pin) = value;
136	  __asm__ volatile ("dsb" : : : "memory");
137	}
