139	static void bk7258_ap_heartbeat_led_write(bool on)
140	{
141	  uint32_t config =
142	    bk7258_ap_gpio_read(BOARD_AP_HEARTBEAT_LED_PIN);
143	  bool high = BOARD_AP_HEARTBEAT_LED_ACTIVE_HIGH ? on : !on;
144	
145	  if (high)
146	    {
147	      config |= BK7258_GPIO_OUTPUT_VALUE;
148	    }
149	  else
150	    {
151	      config &= ~BK7258_GPIO_OUTPUT_VALUE;
152	    }
153	
154	  bk7258_ap_gpio_write(BOARD_AP_HEARTBEAT_LED_PIN, config);
155	}
156	
157	static void bk7258_ap_heartbeat_led_initialize(void)
158	{
159	  uint32_t config =
160	    bk7258_ap_gpio_read(BOARD_AP_HEARTBEAT_LED_PIN);
161	
162	  /* Select ordinary GPIO, disable input and pulls, enable output, and seed the
163	   * inactive level before the task starts toggling the pin. */
164	
165	  config &= ~(BK7258_GPIO_OUTPUT_VALUE |
166	              BK7258_GPIO_INPUT_ENABLE |
167	              BK7258_GPIO_OUTPUT_DISABLE |
168	              BK7258_GPIO_PULL_MODE |
169	              BK7258_GPIO_PULL_ENABLE |
170	              BK7258_GPIO_SECOND_FUNC);
171	  bk7258_ap_gpio_write(BOARD_AP_HEARTBEAT_LED_PIN, config);
172	  bk7258_ap_heartbeat_led_write(false);
173	}
