175	static int bk7258_ap_panic_notify(struct notifier_block *block,
176	                                  unsigned long action, void *data)
177	{
178	  (void)block;
179	  (void)data;
180	
181	  /* PANIC_TASK can describe a task-local assertion. Only kernel panic stages
182	   * are fatal evidence for this AP instance. */
183	
184	  if (action != PANIC_TASK)
185	    {
186	      bk7258_ap_record_fault(BK7258_AP_FAULT_PANIC_BASE |
187	                             ((uint32_t)action & UINT32_C(0xff)));
188	    }
189	
190	  return 0;
191	}
