221	static int bk7258_ap_health_thread(int argc, char *argv[])
222	{
223	  bool led_on = true;
224	  int ret;
225	
226	  (void)argc;
227	  (void)argv;
228	
229	  for (; ; )
230	    {
231	      ret = nxsig_usleep(1000 * 1000);
232	      if (ret < 0)
233	        {
234	          bk7258_ap_record_fault(BK7258_AP_FAULT_SLEEP_BASE |
235	                                 ((uint32_t)-ret & UINT32_C(0xff)));
236	          bk7258_ap_heartbeat_led_write(false);
237	          return ret;
238	        }
239	
240	      led_on = !led_on;
241	      bk7258_ap_heartbeat_led_write(led_on);
242	      bk7258_ap_record_heartbeat();
243	    }
244	
245	  return 0;
246	}
