248	static void bk7258_ap_initialize(void)
249	{
250	  int ret;
251	
252	  /* board_late_initialize() runs before nsh_main. Keep board health and AMP
253	   * setup in kernel workers so the standard NSH entry can own /dev/console.
254	   */
255	
256	  syslog(LOG_INFO, "BK7258: bk7258_ap_initialize called\n");
257	
258	  panic_notifier_chain_register(&g_bk7258_ap_panic_notifier);
259	  bk7258_ap_heartbeat_led_initialize();
260	  bk7258_ap_heartbeat_led_write(true);
261	  bk7258_ap_record_mark_scheduler();
262	
263	  /* Initialize audio devices first (before RPTUN which may return early) */
264	
265	#ifdef CONFIG_AUDIO_BK7258
266	  syslog(LOG_INFO, "BK7258: Initializing audio devices...\n");
267	
268	  /* Register the DevKit PA control ops before the playback device is
269	   * created so the driver never runs with an unknown PA state.
270	   */
271	
272	  ret = bk7258_devkit_audio_pa_register();
273	  if (ret < 0)
274	    {
275	      syslog(LOG_ERR, "BK7258 PA registration failed: %d; "
276	                      "playback device disabled\n", ret);
277	    }
278	  else
279	    {
280	      ret = bk7258_audio_playback_initialize();
281	      if (ret < 0)
282	        {
283	          syslog(LOG_ERR, "BK7258 playback audio init failed: %d\n", ret);
284	        }
285	      else
286	        {
287	          syslog(LOG_INFO, "BK7258: Playback device registered OK\n");
288	        }
289	    }
290	
291	#ifdef CONFIG_AUDIO_BK7258_CAPTURE
292	  ret = bk7258_audio_capture_initialize();
293	  if (ret < 0)
294	    {
295	      syslog(LOG_ERR, "BK7258 capture audio init failed: %d\n", ret);
296	    }
297	  else
298	    {
299	      syslog(LOG_INFO, "BK7258: Capture device registered OK\n");
300	    }
301	#endif
302	#endif
303	
304	  /* Initialize buttons (non-fatal if it fails) */
