308	  if (ret < 0)
309	    {
310	      syslog(LOG_ERR, "BK7258 button init failed: %d\n", ret);
311	    }
312	  else
313	    {
314	      syslog(LOG_INFO, "BK7258: /dev/btn0 registered OK\n");
315	    }
316	#endif
317	
318	#ifdef CONFIG_RPTUN
319	  ret = kthread_create("bk7258-amp-init", 95, 4096,
320	                       bk7258_ap_amp_initialize, NULL);
321	  if (ret < 0)
322	    {
323	      bk7258_ap_record_fault(UINT32_C(0x52505400) |
324	                             ((uint32_t)-ret & UINT32_C(0xff)));
325	      bk7258_ap_heartbeat_led_write(false);
326	    }
